window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[56]={"id":"056","numero":56,"titre":"Enfant handicapé","objectifs":[{"id":"56-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du handicap","contenu":"<p>Le handicap se définit aujourd'hui à travers la <strong><span class=\"kw-def\">CIF</span></strong>\n      (<span class=\"kw-def\">Classification</span> internationale du fonctionnement, du handicap et de la santé), adoptée par l'<span class=\"kw-def\">OMS</span>\n      — une <span class=\"kw-clinique\">évolution</span> du modèle de Wood (1980). Le handicap n'est <strong>ni purement médico-<span class=\"kw-ttt\">biologique</span></strong>\n      (la déficience), <strong>ni purement social</strong> (la restriction de participation), mais une\n      <strong>interaction dynamique</strong> entre l'état de santé de la personne et son environnement.</p>\n\n      <p>Chez l'enfant, l'<span class=\"kw-def\">enfant en situation de handicap</span> est défini comme\n      « un enfant présentant <strong>une ou plusieurs déficiences</strong>, n'ayant ni <span class=\"kw-clinique\">les</span> activités ni la\n      participation attendues, selon la CIF, pour son groupe d'âge dans la société dans laquelle il vit ».</p>\n\n      <p>Le handicap résulte de l'interaction entre trois conséquences du problème de santé et deux familles\n      de facteurs :</p>\n\n      <table >\n        <thead>\n          <tr><th>Composante CIF</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Déficiences</strong></td>\n            <td>Atteinte des <span class=\"kw-clinique\">fonctions et structures du corps</span> : neurologiques,\n            musculaires, sensorielles…</td>\n          </tr>\n          <tr>\n            <td><strong>Limitations d'activité</strong></td>\n            <td>Difficulté à réaliser des actions du quotidien : <span class=\"kw-clinique\">marcher</span>,\n            <span class=\"kw-clinique\">écrire</span>, <span class=\"kw-clinique\">parler</span>…</td>\n          </tr>\n          <tr>\n            <td><strong>Restriction de participation</strong></td>\n            <td>Limitation de l'intégration sociale : école, loisirs, vie de famille</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs environnementaux</strong></td>\n            <td>Obstacles ou facilitateurs : accessibilité, soins disponibles, soutien familial</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs personnels</strong></td>\n            <td>État psychologique, motivation, capacités d'adaptation de l'enfant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Spécificité pédiatrique de la CIF.</strong> Dans ses premières années, l'enfant est\n        <strong>dépendant de ses aidants naturels</strong> : son niveau de participation et de fonctionnement\n        dépend fortement de son <span class=\"kw-def\">environnement proche</span>, de son <span class=\"kw-chiffre\">âge</span>\n        et de sa <span class=\"kw-def\">trajectoire développementale</span>. La maturation cérébrale et la croissance\n        musculo-squelettique exposent au risque de <span class=\"kw-alerte\">déformations neuro-orthopédiques secondaires</span>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Cadre législatif.</strong> La loi pose le principe d'un <span class=\"kw-def\">droit à compensation</span>\n        des conséquences du handicap, <strong>quels que soient l'origine et la nature de la déficience, l'âge ou\n        le mode de vie</strong> de la personne.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 118 — Personne handicapé · 119 — Soins et accompagnement dans la maladie chronique et le handicap</em></p>","frequence":0},{"id":"56-2","rang":"A","rubrique":"Définition","titre":"Connaître la typologie du handicap de l’enfant","contenu":"<p>La typologie du handicap de l'enfant se décline selon le <strong>type de déficience principale</strong>\n      — c'est elle qui oriente la structure de prise en charge :</p>\n\n      <table >\n        <thead>\n          <tr><th>Type de handicap</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Moteur</span></strong></td><td>Déficit du tonus, de la motricité, de la posture (ex. paralysie cérébrale)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Sensoriel</span></strong></td><td><span class=\"kw-clinique\">Auditif</span> et <span class=\"kw-clinique\">visuel</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Intellectuel / cognitif</span></strong></td><td>Trouble du développement intellectuel, des fonctions exécutives, des apprentissages</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Psychique</span></strong></td><td>Troubles du comportement, de la régulation émotionnelle</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Troubles du neurodéveloppement</span></strong></td><td>Dont <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">troubles du spectre autistique</span> (TSA)</td></tr>\n        </tbody>\n      </table>\n\n      <p>Trois notions doivent être <strong>soigneusement distinguées</strong> — piège classique EDN :</p>\n\n      <table >\n        <thead>\n          <tr><th>Notion (à distinguer)</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Polyhandicap</span></strong></td>\n            <td>Dysfonctionnement cérébral <strong>précoce</strong> (avant <span class=\"kw-chiffre\">&lt; 2 ans</span>),\n            de caractère <span class=\"kw-alerte\">irréversible</span> ; graves perturbations multiples et\n            <strong>évolutives</strong> de l'efficience motrice, perceptive, cognitive et de la communication ;\n            signes autistiques possibles, transitoires ou durables. Crée une <span class=\"kw-alerte\">dépendance majeure</span>\n            dans toutes <span class=\"kw-clinique\">les</span> dimensions de la vie.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Multi-handicap</span></strong><br>(ou pluri-handicap)</td>\n            <td>Coexistence de plusieurs déficiences chez un même enfant, <strong>sans pouvoir dire laquelle\n            génère le plus de handicap</strong> — ex. déficience auditive sévère + <span class=\"kw-clinique\">déficit moteur</span> d'une\n            paralysie cérébrale post-<span class=\"kw-etio\">CMV</span> — ce qui complique le choix de la structure d'accompagnement.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Sur-handicap</span></strong></td>\n            <td>Situation résultant de <span class=\"kw-etio\">déficiences secondaires</span>, non directement\n            liées à la pathologie initiale mais à la <strong>situation de handicap préexistante</strong>\n            — ex. rétraction du tendon d'Achille → <span class=\"kw-clinique\">équin</span> sur spasticité ;\n            <span class=\"kw-clinique\">douleurs</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 89 — Altération fonction auditive</em></p>","frequence":0},{"id":"56-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principes d’évaluation et d’examen clinique","contenu":"<p>L'évaluation d'un enfant en situation de handicap est <strong>rigoureuse, multidisciplinaire et\n      coordonnée</strong> : c'est le point de départ nécessaire pour comprendre et anticiper <span class=\"kw-clinique\">les</span> besoins de\n      l'enfant et de sa famille.</p>\n\n      <p>Comme chez l'adulte, elle procède <strong>à partir de la <span class=\"kw-def\">CIF</span></strong> et\n      explore quatre domaines :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">déficiences</span> (fonctions et structures du corps) ;</li>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">activités</span> et leurs limitations ;</li>\n        <li>la <span class=\"kw-def\">participation</span> sociale et ses restrictions ;</li>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-def\">facteurs environnementaux et personnels</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Outils adaptés à l'âge.</strong> Chaque domaine est évalué avec des outils calibrés sur\n        l'<span class=\"kw-chiffre\">âge chronologique</span> de l'enfant — ou l'<span class=\"kw-chiffre\">âge corrigé avant 2 ans</span>\n        pour <span class=\"kw-clinique\">les</span> enfants nés avant <span class=\"kw-chiffre\">37 SA</span>. Les attendus sont comparés à ceux d'un enfant\n        du même âge. La <span class=\"kw-def\">participation sociale</span> de l'enfant correspond à la\n        <strong>scolarité</strong>, à la vie familiale et aux activités de loisirs (club sportif, association).\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Évaluations répétées dans le temps.</strong> Il faut proposer des évaluations\n        <strong>régulières, à différents âges</strong>, même si une première évaluation est satisfaisante :\n        certains déficits (cognitifs notamment) se <span class=\"kw-alerte\">démasquent plus tard</span>, à l'occasion\n        du développement. Une <span class=\"kw-alerte\">stagnation</span> du développement ou une\n        <span class=\"kw-alerte\">dégradation inattendue</span> doit faire <strong>reconsidérer le diagnostic\n        étiologique</strong>.\n      </div>\n\n      <p>L'<strong>environnement immédiat</strong> — parents, aidants naturels — est un facteur majeur à prendre\n      en compte. Facteurs <span class=\"kw-etio\">aggravants</span> du handicap : <span class=\"kw-etio\">faible niveau\n      scolaire parental</span>, <span class=\"kw-etio\">vulnérabilités psycho-affectives et socio-économiques</span>\n      élevées.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 55 — Développement psychomoteur</em></p>","frequence":0},{"id":"56-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge dont les principes de scolarisation","contenu":"<p>L'accompagnement de l'enfant handicapé et de sa famille repose sur un <strong>projet triple</strong>,\n      dont <span class=\"kw-clinique\">les</span> objectifs sont fixés <strong>avec l'enfant et sa famille</strong> et régulièrement réévalués\n      tout au long de la croissance :</p>\n\n      <table >\n        <thead>\n          <tr><th>Axe du projet</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Thérapeutique</span></strong></td><td>Médical, paramédical, rééducatif, psychologique</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Éducatif</span></strong></td><td>Scolarité, accès aux apprentissages</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Social</span></strong></td><td>Familial, environnement, <strong>maintien à domicile</strong>, aides et compensations</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Précocité.</strong> La prise en charge démarre <strong>dès l'apparition d'un déficit ou d'un\n        décalage</strong>, <span class=\"kw-alerte\">même en l'absence de diagnostic étiologique formel</span>\n        — pour ne pas prendre de retard. Priorité au <strong>maintien dans le milieu familial</strong> et à\n        l'intégration en <strong>milieu scolaire ordinaire</strong>.\n      </div>\n\n      <p>La <strong>scolarisation</strong> est un <span class=\"kw-def\">droit opposable</span> : l'éducation est\n      obl<span class=\"kw-chiffre\">iga</span>toire de <span class=\"kw-chiffre\">3 à 16 ans</span> et tout enfant — y compris en situation de handicap —\n      est inscrit dans un établissement scolaire de référence.</p>\n\n      <p>Le <strong><span class=\"kw-def\">PPS</span></strong> (Projet personnalisé de scolarisation) définit <span class=\"kw-clinique\">les</span>\n      besoins particuliers de l'enfant : aide humaine, aménagement des enseignements, matériel pédagogique\n      adapté, dispense d'un ou plusieurs enseignements. Il est élaboré par l'équipe pluridisciplinaire de la\n      <span class=\"kw-def\">MDPH</span>, sur proposition de l'<span class=\"kw-def\">équipe de suivi de la\n      scolarisation (ESS)</span>, avec un <strong>enseignant référent</strong>. Il s'adresse aux enfants\n      <strong>reconnus handicapés par la CDAPH</strong>.</p>\n\n      <p>Le <span class=\"kw-def\">PPS</span> ne doit pas être confondu avec trois autres dispositifs :</p>\n\n      <table >\n        <thead>\n          <tr><th>Dispositif</th><th>Indication / particularité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">PPS</span></strong></td>\n            <td><strong>Indication :</strong> enfant reconnu handicapé par la <span class=\"kw-def\">CDAPH</span><br>\n            <strong>Particularité :</strong> élaboré par la MDPH ; valable quel que soit le lieu de\n            scolarisation (classe ordinaire, ULIS, CNED…)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">PAI</span></strong><br>(projet d'accueil individualisé)</td>\n            <td><strong>Indication :</strong> <span class=\"kw-etio\">pathologie organique invalidante</span>\n            (<span class=\"kw-ci\">allergie</span>, <span class=\"kw-def\">asthme</span>, <span class=\"kw-etio\">maladie cœliaque</span>…)<br>\n            <strong>Particularité :</strong> précise <span class=\"kw-clinique\">les</span> adaptations en collectivité ; établi avec le médecin\n            scolaire ou de PMI</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">PAP</span></strong><br>(plan d'accompagnement personnalisé)</td>\n            <td><strong>Indication :</strong> <span class=\"kw-alerte\">troubles des apprentissages uniquement</span>\n            (troubles « dys »)<br>\n            <strong>Particularité :</strong> <span class=\"kw-alerte\">sans reconnaissance de handicap par la MDPH</span>\n            (sinon c'est un <span class=\"kw-def\">PPS</span>) ; demandé via le médecin scolaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">PPRE</span></strong><br>(programme personnalisé de réussite éducative)</td>\n            <td><strong>Indication :</strong> dispositif <strong>purement pédagogique</strong> (non médical)<br>\n            <strong>Particularité :</strong> obl<span class=\"kw-chiffre\">iga</span>toire en cas de redoublement ; à l'initiative de l'équipe\n            pédagogique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Forfait précoce.</strong> Un <span class=\"kw-def\">forfait de soins de 12 mois</span> permet la\n        prise en charge par l'Assurance maladie des bilans et interventions des <strong>ergothérapeutes</strong>,\n        <strong>psychomotriciens</strong> et <strong>psychologues</strong> pour <span class=\"kw-clinique\">les</span> enfants de\n        <span class=\"kw-chiffre\">0 à 6 ans révolus</span> avec suspicion de <span class=\"kw-def\">trouble du\n        neurodéveloppement (TND)</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 122 — Réeducation - réadaptation · 119 — Soins et accompagnement dans la maladie chronique et le handicap</em></p>","frequence":2},{"id":"56-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître la multidisciplinarité de la prise en charge","contenu":"<p>La prise en charge fait appel à une <strong>équipe pluriprofessionnelle</strong> entraînée au\n      développement de l'enfant. L'<span class=\"kw-def\">axe rééducatif</span> adapte <span class=\"kw-clinique\">les</span> interventions au\n      déficit évalué :</p>\n\n      <table >\n        <thead>\n          <tr><th>Déficit / limitation</th><th>Intervenants</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Troubles moteurs et posturaux</span></td><td>Kinésithérapie ; ergothérapie ; psychomotricité</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles de l'oralité, de la déglutition</span></td><td>Orthophonie ; kinésithérapie ; ergothérapie ; diététicienne</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles de la communication et du langage</span></td><td>Orthophonie ; ORL ; audioprothésiste</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles visuels</span></td><td>Ophtalmologie ; orthoptie</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles du comportement et émotionnels</span></td><td>Psychomotricité ; éducation spécialisée ; psychologie ; pédopsychiatrie</td></tr>\n          <tr><td><span class=\"kw-clinique\">Déficits cognitifs, troubles des apprentissages</span></td><td>Neuropsychologie ; orthophonie ; psychomotricité</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège du remboursement.</strong> Tous <span class=\"kw-clinique\">les</span> intervenants ne sont pas pris en charge par\n        l'Assurance maladie :<br>\n        <strong>Remboursés CPAM :</strong> kinésithérapie ; orthophonie ; orthoptie ; nutritionniste<br>\n        <strong>Non remboursés CPAM</strong> (mais possible via MDPH ou mutuelle) :\n        <span class=\"kw-alerte\">ergothérapeute</span> ; <span class=\"kw-alerte\">psychomotricien</span> ;\n        <span class=\"kw-alerte\">diététicien</span>\n      </div>\n\n      <p>Le <strong><span class=\"kw-def\">médecin référent du handicap de l'enfant</span></strong> garantit le\n      <span class=\"kw-def\">pronostic</span> fonctionnel. Ses missions :</p>\n      <ul>\n        <li>surveiller le développement <span class=\"kw-clinique\">staturo-pondéral</span>, l'état\n        <span class=\"kw-clinique\">neuro-orthopédique</span>, la <span class=\"kw-clinique\">douleur</span>, l'état\n        psychologique et neurocognitif ;</li>\n        <li><strong>coordonner et réévaluer</strong> la pertinence, la tolérance et l'efficacité des prises\n        en charge ;</li>\n        <li>éviter la <span class=\"kw-alerte\">surcharge des emplois du temps</span> et hiérarchiser <span class=\"kw-clinique\">les</span> priorités.</li>\n      </ul>\n\n      <p>Lieux d'exercice : secteur <strong>libéral</strong>, secteur <strong>sanitaire</strong> (hôpital,\n      centre de rééducation), structures <strong>ambulatoires</strong> (CAMSP, CMPP, SESSAD), <strong>institutions</strong>\n      (IME, IEM).</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 122 — Réeducation - réadaptation</em></p>","frequence":0},{"id":"56-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la maison départementale des personnes handicapées (MDPH)","contenu":"<p>La <strong><span class=\"kw-def\">MDPH</span></strong> (Maison départementale des personnes handicapées)\n      existe dans <strong>chaque département</strong>. Selon le principe d'un <strong>lieu unique</strong>, elle\n      offre un <span class=\"kw-def\">accès unique aux droits et prestations</span> des personnes handicapées.</p>\n\n      <p>Ses missions :</p>\n      <ul>\n        <li>assurer l'organisation de la <strong><span class=\"kw-def\">CDAPH</span></strong> (Commission des droits\n        et de l'autonomie des personnes handicapées) et le <span class=\"kw-def\">suivi</span> de ses décisions ;</li>\n        <li>gérer le <span class=\"kw-def\">fonds départemental de compensation</span> du handicap.</li>\n      </ul>\n\n      <p>Le <strong>dossier MDPH</strong> (retiré en ligne ou à la MDPH) est constitué par <span class=\"kw-clinique\">les</span>\n      <strong>parents</strong> — ou le titulaire de l'autorité parentale — souvent aidés par l'assistante\n      sociale. Il comprend :</p>\n      <ul>\n        <li>le <span class=\"kw-def\">projet de vie</span> — rempli par la famille ;</li>\n        <li>la <span class=\"kw-def\">partie médicale</span> — remplie par le médecin référent de l'enfant ;</li>\n        <li>le <span class=\"kw-def\">GEVA-Sco</span> — pour <span class=\"kw-clinique\">les</span> enfants d'âge scolaire, intégrant les observations\n        des enseignants.</li>\n      </ul>\n\n      <p>La <span class=\"kw-def\">CDAPH</span> évalue le <span class=\"kw-chiffre\">taux d'incapacité</span> et <span class=\"kw-clinique\">les</span> besoins\n      de compensation, puis élabore un <strong><span class=\"kw-def\">PPC</span></strong> (Plan personnalisé de\n      compensation) — dont le <span class=\"kw-def\">PPS</span> fait partie pour les enfants d'âge scolaire.\n      Prestations et services attribués après décision : aménagements de scolarisation (AESH, AVS, matériel,\n      SESSAD…), <span class=\"kw-def\">PCH</span>, <span class=\"kw-def\">carte d'invalidité</span>,\n      <span class=\"kw-def\">AEEH</span> et compléments, <span class=\"kw-def\">AJPP</span>.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Trois structures <span class=\"kw-alerte\">ne relèvent pas de la MDPH</span>\n        — elles sont en accès direct, sans notification : <span class=\"kw-alerte\">CAMSP</span>\n        (<span class=\"kw-chiffre\">&lt; 6 ans</span>), <span class=\"kw-alerte\">CMPP</span> (<span class=\"kw-chiffre\">&lt; 20 ans</span>),\n        <span class=\"kw-alerte\">CMP</span> (<span class=\"kw-chiffre\">≥ 16 ans</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 118 — Personne handicapé</em></p>","frequence":0},{"id":"56-7","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les grandes situations du handicap de l’enfant en France","contenu":"<p>Quelques repères épidémiologiques du handicap de l'enfant en France :</p>\n\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Déficience</td><td>Concerne <span class=\"kw-chiffre\">&lt; 1 %</span> des enfants nés en France, soit ≈ <span class=\"kw-chiffre\">7 000 enfants/an</span></td></tr>\n          <tr><td><span class=\"kw-def\">Prévalence</span> du handicap de l'enfant</td><td>≈ <span class=\"kw-chiffre\">2,5 %</span>, tous handicaps confondus</td></tr>\n          <tr><td>Polyhandicap</td><td>≈ <span class=\"kw-chiffre\">9 400 enfants</span> et <span class=\"kw-chiffre\">23 000 adultes</span> ; <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">0,50 à 0,73 / 1 000</span></td></tr>\n          <tr><td>Âge de début</td><td>Origine <span class=\"kw-etio\">prénatale ou périnatale</span> dans <span class=\"kw-chiffre\">&gt; 50 %</span> des cas</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Plasticité cérébrale.</strong> La capacité des réseaux neuronaux à se (ré)organiser est\n        <strong>intense lors des <span class=\"kw-chiffre\">1 000 premiers jours</span></strong>. Elle est influencée\n        par des facteurs <span class=\"kw-etio\">intrinsèques</span> (génétiques, épigénétiques) et\n        <span class=\"kw-etio\">extrinsèques</span> (nutrition, éducation, rééducation, toxiques, agents\n        <span class=\"kw-etio\">infectieux</span>…).\n      </div>\n\n      <p>Le handicap a un <strong>retentissement large</strong> :</p>\n      <ul>\n        <li><strong>Sur l'enfant :</strong> retentissement sur la santé, la <span class=\"kw-clinique\">croissance\n        musculo-squelettique</span>, <span class=\"kw-clinique\">les</span> acquisitions psychoaffectives, psychomotrices et cognitives.</li>\n        <li><strong>Sur <span class=\"kw-clinique\">les</span> interactions :</strong> perturbe la qualité des liens avec les aidants naturels\n        (<span class=\"kw-clinique\">attachement</span>), favorise <span class=\"kw-alerte\">violence, abus et négligence</span>.</li>\n        <li><strong>Sur la fratrie :</strong> sentiment que <span class=\"kw-clinique\">les</span> parents ont moins de temps, discrimination par\n        les pairs.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 30 — Prématurité, RCIU · 89 — Altération fonction auditive</em></p>","frequence":0},{"id":"56-8","rang":"B","rubrique":"Étiologies","titre":"Connaître la démarche étiologique du handicap","contenu":"<p>La <strong>démarche étiologique</strong> situe le handicap dans le temps : plus de\n      <span class=\"kw-chiffre\">50 %</span> des handicaps de l'enfant prennent leur origine en période\n      <span class=\"kw-etio\">prénatale ou périnatale</span>. Deux causes majeures à connaître : la\n      <span class=\"kw-etio\">prématurité</span> et l'<span class=\"kw-etio\">anoxo-ischémie cérébrale</span>.</p>\n\n      <p><span class=\"kw-clinique\">Les</span> <strong>premières causes par type de handicap</strong> sont des classiques de QCM :</p>\n\n      <table >\n        <thead>\n          <tr><th>Type de handicap</th><th>1ʳᵉ cause</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Handicap <span class=\"kw-clinique\">moteur</span></td><td><span class=\"kw-etio\">Paralysie cérébrale</span></td></tr>\n          <tr><td>Retard mental <strong><span class=\"kw-etio\">héréditaire</span></strong></td><td><span class=\"kw-etio\">Trisomie 21</span></td></tr>\n          <tr><td>Retard mental <strong>non <span class=\"kw-etio\">héréditaire</span></strong></td><td><span class=\"kw-etio\">Syndrome d'alcoolisation fœtale</span></td></tr>\n          <tr><td>Troubles spécifiques des apprentissages</td><td><span class=\"kw-etio\">Dyslexie-dysorthographie</span></td></tr>\n          <tr><td>Surdité <strong><span class=\"kw-etio\">congénitale</span></strong></td><td><span class=\"kw-etio\">Infection materno-fœtale à CMV</span></td></tr>\n          <tr><td>Surdité <strong><span class=\"kw-etio\">acquise</span></strong></td><td><span class=\"kw-etio\">Otite séromuqueuse</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche en pratique.</strong> Le <span class=\"kw-def\">diagnostic étiologique</span> fait partie de l'<span class=\"kw-def\">axe\n        médical</span> et peut nécessiter des examens complémentaires. Mais la prise en charge démarre\n        <strong>sans attendre</strong> ce diagnostic, qui <span class=\"kw-alerte\">ne vient parfois jamais</span>.\n        Une <span class=\"kw-alerte\">stagnation</span> ou une <span class=\"kw-alerte\">dégradation inattendue</span> de\n        l'état clinique doit faire <strong>reconsidérer le <span class=\"kw-def\">diagnostic étiologique</span></strong>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Annonce</span> diagnostique.</strong> L'<span class=\"kw-def\">annonce</span> du handicap est un <strong>acte médical essentiel</strong>,\n        qui demande du temps. <span class=\"kw-clinique\">Les</span> équipes doivent s'assurer que le handicap — <strong>même en l'absence\n        d'étiologie formelle</strong> — a été annoncé à la famille dans un cadre dédié de\n        <span class=\"kw-def\">consultation d'annonce</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 30 — Prématurité, RCIU · 32 — Evaluation du nouveau-né · 57 — Maltraitance, enfant en danger</em></p>","frequence":0},{"id":"56-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les modalités de l’orientation en fonction du handicap","contenu":"<p>L'orientation des enfants en situation de handicap est <strong>pilotée par la MDPH via la CDAPH</strong>,\n      à partir du <span class=\"kw-def\">PPC</span> et du <span class=\"kw-def\">PPS</span>. <span class=\"kw-clinique\">Les</span> structures se classent\n      selon <strong>l'autorité qui décide de l'orientation</strong> :</p>\n\n      <table >\n        <thead>\n          <tr><th>Autorité d'orientation</th><th>Structures</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Orientation <span class=\"kw-def\">MDPH</span></strong></td>\n            <td><strong>Scolaire :</strong> ULIS ; CLIS<br>\n            <strong>Services médico-sociaux :</strong> SESSAD ; SSAD ; SAFEP ; SSEFIS ; SAAAIS<br>\n            <strong>Instituts :</strong> IME ; IEM ; IES ; ITEP</td>\n          </tr>\n          <tr>\n            <td><strong>Orientation <span class=\"kw-def\">Éducation nationale</span></strong></td>\n            <td>SEGPA (enseignement général et professionnel adapté) ; EREA (établissement régional\n            d'enseignement adapté)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Accès libre</span></strong><br>(sans dossier)</td>\n            <td>Classe ordinaire ± PAI ; CNED ; enseignement à l'hôpital ; <span class=\"kw-alerte\">CAMSP</span> ;\n            <span class=\"kw-alerte\">CMPP</span> ; <span class=\"kw-alerte\">CMP</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><span class=\"kw-clinique\">Les</span> établissements et services sont, pour la plupart, <strong>organisés selon le type de déficience\n      principale</strong> :</p>\n\n      <table >\n        <thead>\n          <tr><th>Structure</th><th>Public</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">IME</span></strong></td><td>Déficience <span class=\"kw-clinique\">intellectuelle</span> (établissements aussi spécialisés pour déficience auditive, visuelle, polyhandicap)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">IEM</span></strong></td><td>Déficience <span class=\"kw-clinique\">motrice</span> sévère, incompatible avec le milieu ordinaire</td></tr>\n          <tr><td><strong><span class=\"kw-def\">ITEP</span></strong></td><td>Troubles du <span class=\"kw-clinique\">comportement</span>, <strong>sans pathologie psychotique ni déficience intellectuelle</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">SESSAD</span></strong></td><td>Déficiences intellectuelles et motrices, polyhandicap — accompagnement ambulatoire sur <span class=\"kw-clinique\">les</span> lieux de vie</td></tr>\n          <tr><td><strong><span class=\"kw-def\">SAFEP</span></strong></td><td>Déficience sensorielle, enfant <span class=\"kw-chiffre\">&lt; 3 ans</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">SSEFIS</span></strong></td><td>Déficient <span class=\"kw-clinique\">auditif</span>, <span class=\"kw-chiffre\">&gt; 3 ans</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">SAAAIS</span></strong></td><td>Déficient <span class=\"kw-clinique\">visuel</span>, <span class=\"kw-chiffre\">&gt; 3 ans</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">IMPRO / IMP</span></strong></td><td>Adolescents <span class=\"kw-chiffre\">&gt; 14 ans</span> — formation professionnelle</td></tr>\n        </tbody>\n      </table>\n\n      <p>D'autres structures s'orientent selon l'<strong>âge</strong> de l'enfant :</p>\n\n      <table >\n        <thead>\n          <tr><th>Structure</th><th>Âge / rôle</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">PMI</span></strong></td><td><span class=\"kw-chiffre\">&lt; 6 ans</span> — protection maternelle et infantile, <span class=\"kw-def\">dépistage</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">CAMSP</span></strong></td><td><span class=\"kw-chiffre\">0-6 ans</span> — déficits sensoriels, intellectuels, moteurs ; <span class=\"kw-def\">dépistage</span> et rééducation ambulatoire ; <strong>accès direct</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">CMPP</span></strong></td><td><span class=\"kw-chiffre\">0-20 ans</span> — troubles psychoaffectifs, psychomoteurs, des apprentissages ; <strong>accès direct</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">CMP</span></strong></td><td><span class=\"kw-chiffre\">≥ 16 ans</span> — troubles psychiques ; rattaché à un hôpital et <strong>sectorisé</strong></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Milieu ordinaire ou spécialisé.</strong> La scolarisation se fait en priorité en\n        <strong>milieu ordinaire</strong> — classe ordinaire avec aide humaine (<span class=\"kw-def\">AESH</span>,\n        <span class=\"kw-def\">AVS</span>) ou classe adaptée (<span class=\"kw-def\">ULIS</span> sur orientation MDPH,\n        <span class=\"kw-def\">SEGPA</span> sur orientation Éducation nationale). Le <strong>milieu spécialisé</strong>\n        (établissements médico-sociaux) est réservé aux situations où <span class=\"kw-clinique\">les</span> déficiences, limitations d'activité ou\n        contraintes thérapeutiques sont <span class=\"kw-alerte\">trop importantes</span>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Transition après <span class=\"kw-chiffre\">18 ans</span>.</strong> Selon l'autonomie : <span class=\"kw-def\">RQTH</span>\n        (reconnaissance de la qualité de travailleur handicapé) pour un emploi adapté ;\n        <span class=\"kw-def\">ESAT</span> (établissement et service d'aide par le travail) ;\n        <span class=\"kw-def\">FAM / MAS</span> (foyer d'accueil médicalisé / maison d'accueil spécialisée) pour <span class=\"kw-clinique\">les</span>\n        situations de handicap sévère.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 118 — Personne handicapé · 122 — Réeducation - réadaptation</em></p>","frequence":3}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"4cd63b973b31","n":56,"o":"56-1","u":"Définition","t":"Connaître la définition du handicap","q":"Quels sont les deux types de facteurs qui influencent l'interaction entre l'état de santé et l'environnement dans le modèle CIF du handicap ?","a":"<p>Les deux types de facteurs sont :</p><ul><li>Les <strong>facteurs environnementaux</strong> : obstacles ou facilitateurs (ex: accessibilité, soutien familial).</li><li>Les <strong>facteurs personnels</strong> : état psychologique, motivation, capacités d'adaptation de l'individu.</li></ul>"},{"i":"5558f3120b79","n":56,"o":"56-1","u":"Définition","t":"Connaître la définition du handicap","q":"Quelles sont les trois composantes du handicap définies par la Classification Internationale du Fonctionnement, du handicap et de la santé (CIF) ?","a":"<p>Selon la CIF, le handicap comprend trois composantes principales :</p><ul><li>Les <strong>déficiences</strong> : atteintes des fonctions et structures du corps (ex: neurologiques, sensorielles).</li><li>Les <strong>limitations d'activité</strong> : difficultés à réaliser des actions quotidiennes (ex: marcher, écrire, parler).</li><li>Les <strong>restrictions de participation</strong> : limitations de l'intégration sociale (ex: école, loisirs).</li></ul>"},{"i":"5ed04a1977cc","n":56,"o":"56-1","u":"Définition","t":"Connaître la définition du handicap","q":"Comment la Classification Internationale du Fonctionnement, du handicap et de la santé (CIF) définit-elle l'enfant en situation de handicap en pédiatrie ?","a":"<p>L'enfant en situation de handicap est défini comme \"un enfant présentant une ou plusieurs <strong>déficiences</strong>, n'ayant ni les <strong>activités</strong> ni la <strong>participation</strong> attendues, selon la CIF, pour son groupe d'âge dans la société dans laquelle il vit\".</p>"},{"i":"f1e133211680","n":56,"o":"56-1","u":"Définition","t":"Connaître la définition du handicap","q":"Comment l'Organisation Mondiale de la Santé (OMS) définit-elle le handicap selon la Classification Internationale du Fonctionnement, du handicap et de la santé (CIF) ?","a":"<p>En 2001, l'<strong>OMS</strong> a adopté la <strong>CIF</strong> qui définit le handicap comme une <strong>interaction dynamique</strong> entre l'état de santé d'une personne et son environnement, et non plus comme un problème purement médico-biologique ou social.</p>"},{"i":"654d9b8dff65","n":56,"o":"56-2","u":"Définition","t":"Connaître la typologie du handicap de l’enfant","q":"Qu'est-ce que le sur-handicap chez l'enfant ?","a":"<p>Le sur-handicap est une situation résultant de <strong>déficiences secondaires</strong>. Celles-ci ne sont pas directement liées à la pathologie initiale, mais surviennent en conséquence de la situation de handicap préexistante. Un exemple en est la formation d'une <strong>rétraction du tendon d'Achille</strong> menant à un équin sur une spasticité existante, ou l'apparition de douleurs.</p>"},{"i":"b1ddb8faea5d","n":56,"o":"56-2","u":"Définition","t":"Connaître la typologie du handicap de l’enfant","q":"Quelle est la typologie du handicap de l'enfant basée sur la déficience principale ?","a":"<p>La typologie du handicap de l'enfant est la suivante :</p><ul><li><strong>Moteur</strong> : déficit du tonus, de la motricité, de la posture (ex. paralysie cérébrale).</li><li><strong>Sensoriel</strong> : déficience auditive et visuelle.</li><li><strong>Intellectuel / cognitif</strong> : trouble du développement intellectuel, des fonctions exécutives, des apprentissages.</li><li><strong>Psychique</strong> : troubles du comportement, de la régulation émotionnelle.</li><li><strong>Troubles du neurodéveloppement</strong> : dont les troubles du spectre autistique (TSA).</li></ul>"},{"i":"c5dac3ae7ab1","n":56,"o":"56-2","u":"Définition","t":"Connaître la typologie du handicap de l’enfant","q":"Quelle est la définition du polyhandicap chez l'enfant ?","a":"<p>Le polyhandicap chez l'enfant se caractérise par un <strong>dysfonctionnement cérébral précoce</strong> (avant <strong>2 ans</strong>), de caractère <strong>irréversible</strong>, entraînant de <strong>graves perturbations multiples et évolutives</strong> de l'efficience motrice, perceptive, cognitive et de la communication. Des signes autistiques peuvent être présents, transitoires ou durables. Cette situation crée une <strong>dépendance majeure</strong> dans toutes les dimensions de la vie.</p>"},{"i":"e08da6dd0ac6","n":56,"o":"56-2","u":"Définition","t":"Connaître la typologie du handicap de l’enfant","q":"Comment distinguer le multi-handicap (ou pluri-handicap) d'après sa définition ?","a":"<p>Le multi-handicap (ou pluri-handicap) correspond à la <strong>coexistence de plusieurs déficiences</strong> chez un même enfant, sans qu'il soit possible de déterminer laquelle génère le plus de handicap. Un exemple typique est la coexistence d'une <strong>déficience auditive sévère</strong> et d'un <strong>déficit moteur</strong> lié à une paralysie cérébrale.</p>"},{"i":"00ff43db8bcd","n":56,"o":"56-3","u":"Diagnostic positif","t":"Connaître les principes d’évaluation et d’examen clinique","q":"Quels sont les facteurs environnementaux et personnels majeurs à prendre en compte et les facteurs aggravants du handicap chez l'enfant ?","a":"<ul><li>L'<strong>environnement immédiat</strong> (parents, aidants naturels) est un facteur majeur.</li><li>Les facteurs aggravants principaux sont un <strong>faible niveau scolaire parental</strong> et des <strong>vulnérabilités psycho-affectives et socio-économiques élevées</strong>.</li></ul>"},{"i":"0c9a740c4917","n":56,"o":"56-3","u":"Diagnostic positif","t":"Connaître les principes d’évaluation et d’examen clinique","q":"Comment doit être réalisée l'évaluation des différents domaines chez l'enfant en situation de handicap, notamment en ce qui concerne l'âge ?","a":"<p>Chaque domaine est évalué avec des <strong>outils adaptés et calibrés sur l'âge chronologique de l'enfant</strong> ou sur l'<strong>âge corrigé avant 2 ans pour les enfants nés avant 37 SA</strong>. Les attendus sont ensuite comparés à ceux d'un enfant du même âge.</p>"},{"i":"361d14d7b581","n":56,"o":"56-3","u":"Diagnostic positif","t":"Connaître les principes d’évaluation et d’examen clinique","q":"Quels sont les quatre domaines explorés lors de l'évaluation d'un enfant en situation de handicap, en accord avec la CIF (Classification Internationale du Fonctionnement, du handicap et de la santé) ?","a":"<ul><li>Les <strong>déficiences</strong> (fonctions et structures du corps).</li><li>Les <strong>activités</strong> et leurs limitations.</li><li>La <strong>participation sociale</strong> et ses restrictions.</li><li>Les <strong>facteurs environnementaux et personnels</strong>.</li></ul>"},{"i":"8da53017f46c","n":56,"o":"56-3","u":"Diagnostic positif","t":"Connaître les principes d’évaluation et d’examen clinique","q":"Quels sont les principes généraux d'évaluation d'un enfant en situation de handicap ?","a":"<p>L'évaluation est <strong>rigoureuse</strong>, <strong>multidisciplinaire</strong> et <strong>coordonnée</strong>. Elle est le point de départ pour comprendre et anticiper les besoins de l'enfant et de sa famille.</p>"},{"i":"fa98e7bd5a7d","n":56,"o":"56-3","u":"Diagnostic positif","t":"Connaître les principes d’évaluation et d’examen clinique","q":"Pourquoi et comment les évaluations d'un enfant en situation de handicap doivent-elles être répétées dans le temps ?","a":"<p>Des évaluations régulières sont nécessaires à <strong>différents âges</strong>, car <strong>certains déficits (notamment cognitifs) peuvent se démasquer plus tard</strong> dans le développement. Une <strong>stagnation du développement</strong> ou une <strong>dégradation inattendue</strong> doit faire reconsidérer le diagnostic étiologique.</p>"},{"i":"0bcf609514eb","n":56,"o":"56-4","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge dont les principes de scolarisation","q":"Qu'est-ce que le Projet Personnalisé de Scolarisation (PPS) pour un enfant handicapé et qui l'élabore ?","a":"<p>Le PPS est un document qui définit les <strong>besoins particuliers</strong> de l'enfant en milieu scolaire (aide humaine, aménagements, matériel adapté, dispenses). Il s'adresse aux enfants reconnus handicapés par la <strong>CDAPH</strong> (Commission des droits et de l'autonomie des personnes handicapées).</p><p>Il est élaboré par l'<strong>équipe pluridisciplinaire de la MDPH</strong> (Maison Départementale des Personnes Handicapées), sur proposition de l'<strong>équipe de suivi de la scolarisation (ESS)</strong> et avec un enseignant référent. Il est valable quel que soit le lieu de scolarisation (classe ordinaire, ULIS, CNED, etc.).</p>"},{"i":"7d635397a25a","n":56,"o":"56-4","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge dont les principes de scolarisation","q":"Quelles sont les différences entre un PPS, un PAI, un PAP et un PPRE dans la prise en charge scolaire ?","a":"<ul><li><strong>PPS (Projet Personnalisé de Scolarisation)</strong> : pour les enfants reconnus handicapés par la CDAPH. Élaboré par la MDPH.</li><li><strong>PAI (Projet d'Accueil Individualisé)</strong> : pour les pathologies organiques invalidantes (allergie, asthme, maladie cœliaque). Précise les adaptations en collectivité. Établi avec le médecin scolaire ou de PMI.</li><li><strong>PAP (Plan d'Accompagnement Personnalisé)</strong> : pour les troubles des apprentissages uniquement (troubles « dys »), sans reconnaissance de handicap par la MDPH. Demandé via le médecin scolaire.</li><li><strong>PPRE (Programme Personnalisé de Réussite Éducative)</strong> : dispositif purement pédagogique (non médical). Obligatoire en cas de redoublement. À l'initiative de l'équipe pédagogique.</li></ul>"},{"i":"826514f69f1f","n":56,"o":"56-4","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge dont les principes de scolarisation","q":"Dans quel cadre un forfait précoce peut-il être mis en place pour un enfant ?","a":"<p>Un forfait précoce est un forfait de soins de <strong>12 mois</strong> permettant la prise en charge par l'Assurance maladie des bilans et interventions des <strong>ergothérapeutes</strong>, <strong>psychomotriciens</strong> et <strong>psychologues</strong>.</p><p>Il concerne les enfants de <strong>0 à 6 ans révolus</strong> présentant une suspicion de <strong>trouble du neurodéveloppement (TND)</strong>.</p>"},{"i":"8ff7c95b2738","n":56,"o":"56-4","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge dont les principes de scolarisation","q":"Quels sont les trois axes principaux du projet d'accompagnement d'un enfant handicapé et de sa famille, et à quel moment doit débuter la prise en charge ?","a":"<p>Les trois axes principaux sont :</p><ul><li><strong>Thérapeutique</strong> : médical, paramédical, rééducatif, psychologique.</li><li><strong>Éducatif</strong> : scolarité, accès aux apprentissages.</li><li><strong>Social</strong> : familial, environnement, maintien à domicile, aides et compensations.</li></ul><p>La prise en charge doit débuter de manière <strong>précoce</strong>, dès l'apparition d'un déficit ou d'un décalage, même sans diagnostic étiologique formel, pour éviter tout retard.</p>"},{"i":"cff7d736dc4b","n":56,"o":"56-4","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge dont les principes de scolarisation","q":"Quels sont les principes fondamentaux de la scolarisation des enfants en situation de handicap en France ?","a":"<p>La scolarisation est un <strong>droit opposable</strong>. L'éducation est obligatoire de <strong>3 à 16 ans</strong>, et tout enfant, y compris en situation de handicap, est inscrit dans un établissement scolaire de référence.</p><p>La priorité est donnée au <strong>maintien dans le milieu familial</strong> et à l'<strong>intégration en milieu scolaire ordinaire</strong>.</p>"},{"i":"0254a6a4b00d","n":56,"o":"56-5","u":"Prise en charge","t":"Connaître la multidisciplinarité de la prise en charge","q":"Quelle est la composition de l'équipe prenant en charge un enfant handicapé, et à quoi fait-elle appel ?","a":"<p>La prise en charge d'un enfant handicapé fait appel à une équipe <strong>pluriprofessionnelle</strong>, entraînée au développement de l'enfant.</p>"},{"i":"1abd2ed15777","n":56,"o":"56-5","u":"Prise en charge","t":"Connaître la multidisciplinarité de la prise en charge","q":"Quelles sont les missions du médecin référent du handicap de l'enfant ?","a":"<p>Le médecin référent du handicap garantit le <strong>pronostic fonctionnel</strong> de l'enfant. Ses missions sont de :</p><ul><li>Surveiller le développement <strong>staturo-pondéral</strong>.</li><li>Évaluer l'état <strong>neuro-orthopédique</strong>.</li><li>Prendre en compte et gérer la <strong>douleur</strong>.</li><li>Surveiller l'état <strong>psychologique</strong> et <strong>neurocognitif</strong>.</li><li><strong>Coordonner</strong> et <strong>réévaluer</strong> la pertinence, la tolérance et l'efficacité des prises en charge.</li><li>Éviter la <strong>surcharge des emplois du temps</strong> et hiérarchiser les priorités.</li></ul>"},{"i":"1e6b0a3b2839","n":56,"o":"56-5","u":"Prise en charge","t":"Connaître la multidisciplinarité de la prise en charge","q":"Quelles professions ne sont pas remboursées par la CPAM dans le cadre de la prise en charge du handicap de l'enfant ?","a":"<p>Les professions suivantes ne sont généralement <strong>pas remboursées</strong> directement par la CPAM, mais peuvent l'être via la <strong>MDPH</strong> ou une <strong>mutuelle</strong> :</p><ul><li><strong>Ergothérapeute</strong></li><li><strong>Psychomotricien</strong></li><li><strong>Diététicien</strong></li></ul>"},{"i":"5180b20b3124","n":56,"o":"56-5","u":"Prise en charge","t":"Connaître la multidisciplinarité de la prise en charge","q":"Qui prend en charge les troubles de l'oralité et de la déglutition chez l'enfant handicapé ?","a":"<ul><li><strong>Orthophonie</strong></li><li><strong>Kinésithérapie</strong></li><li><strong>Ergothérapie</strong></li><li><strong>Diététicien</strong></li></ul>"},{"i":"5ab16b94190d","n":56,"o":"56-5","u":"Prise en charge","t":"Connaître la multidisciplinarité de la prise en charge","q":"Quels sont les intervenants clés pour la prise en charge des troubles moteurs et posturaux chez l'enfant handicapé ?","a":"<ul><li><strong>Kinésithérapie</strong></li><li><strong>Ergothérapie</strong></li><li><strong>Psychomotricité</strong></li></ul>"},{"i":"90e4a8a49e4b","n":56,"o":"56-5","u":"Prise en charge","t":"Connaître la multidisciplinarité de la prise en charge","q":"Quels sont les intervenants pour les troubles du comportement et émotionnels de l'enfant handicapé ?","a":"<ul><li><strong>Psychomotricité</strong></li><li><strong>Éducation spécialisée</strong></li><li><strong>Psychologie</strong></li><li><strong>Pédopsychiatrie</strong></li></ul>"},{"i":"092aa2d31f33","n":56,"o":"56-6","u":"Définition","t":"Connaître la définition de la maison départementale des personnes handicapées (MDPH)","q":"Quelle est la définition de la Maison Départementale des Personnes Handicapées (MDPH) ?","a":"<p>La MDPH est une structure départementale qui, selon le principe du <strong>lieu unique</strong>, assure un <strong>accès unique aux droits et prestations</strong> des personnes handicapées.</p>"},{"i":"16a52521df34","n":56,"o":"56-6","u":"Définition","t":"Connaître la définition de la maison départementale des personnes handicapées (MDPH)","q":"Quelles sont les structures d'accès direct qui ne relèvent pas de la MDPH pour les enfants et adolescents ?","a":"<ul><li>Le <strong>CAMSP</strong> (Centre d'Action Médico-Sociale Précoce), pour les enfants de <strong>moins de 6 ans</strong>.</li><li>Le <strong>CMPP</strong> (Centre Médico-Psycho-Pédagogique), pour les enfants de <strong>moins de 20 ans</strong>.</li><li>Le <strong>CMP</strong> (Centre Médico-Psychologique), pour les jeunes de <strong>16 ans et plus</strong>.</li></ul>"},{"i":"3cc100335d2f","n":56,"o":"56-6","u":"Définition","t":"Connaître la définition de la maison départementale des personnes handicapées (MDPH)","q":"Quel est le rôle de la CDAPH au sein du processus MDPH pour un enfant ?","a":"<p>La CDAPH évalue le <strong>taux d'incapacité</strong> et les <strong>besoins de compensation</strong> de l'enfant, puis élabore un <strong>Plan Personnalisé de Compensation (PPC)</strong>. Pour les enfants d'âge scolaire, le PPS (Projet Personnalisé de Scolarisation) fait partie de ce PPC.</p>"},{"i":"68c089ca3c02","n":56,"o":"56-6","u":"Définition","t":"Connaître la définition de la maison départementale des personnes handicapées (MDPH)","q":"Quels sont les éléments constitutifs du dossier MDPH pour un enfant ?","a":"<ul><li>Le <strong>projet de vie</strong>, rempli par la famille.</li><li>La <strong>partie médicale</strong>, remplie par le médecin référent de l'enfant.</li><li>Le <strong>GEVA-Sco</strong> (Guide d'EVAluation scolaire), pour les enfants d'âge scolaire, intégrant les observations des enseignants.</li></ul>"},{"i":"f5d38b8c20c4","n":56,"o":"56-6","u":"Définition","t":"Connaître la définition de la maison départementale des personnes handicapées (MDPH)","q":"Quelles sont les missions principales de la MDPH ?","a":"<ul><li>Assurer l'organisation de la <strong>Commission des Droits et de l'Autonomie des Personnes Handicapées (CDAPH)</strong> et le suivi de ses décisions.</li><li>Gérer le <strong>fonds départemental de compensation du handicap</strong>.</li></ul>"}]};